const __memStore={};
const Storage={
 get(k,f){try{const v=localStorage.getItem('zs:'+k);return v===null?(__memStore[k]??f):JSON.parse(v)}catch{return __memStore[k]??f}},
 set(k,v){__memStore[k]=v;try{localStorage.setItem('zs:'+k,JSON.stringify(v))}catch{}logEvent('storage.set',k+' = '+JSON.stringify(v).slice(0,90));return v}
};
const MockAPI={
 wait(v,ms=80){return new Promise(r=>setTimeout(()=>r(JSON.parse(JSON.stringify(v))),ms))},
 home(){logEvent('api.GET','/api/home');return this.wait({collections:DATA.collections,videos:DATA.videos.slice(0,4),creators:DATA.creators})},
 compilation(id){logEvent('api.GET','/api/compilations/'+id);return this.wait({id:36,title:'Comprehensible Input',videos:DATA.videos})},
 video(id){logEvent('api.GET','/api/videos/'+id);const v=DATA.videos.find(x=>String(x.id)===String(id))||DATA.videos[0];return this.wait({video:v,sentences:DATA.sentences})},
 saveProgress(id,t){Storage.set('progress:'+id,{time:t,updatedAt:Date.now()});logEvent('api.PUT',`/api/progress/${id} time=${t.toFixed(2)}`)},
 toggleWord(word){const key=vocabKey(word),arr=new Set(Storage.get('vocab',[]).map(normalizePhrase)),removed=new Set(Storage.get('vocabRemoved',[]));const sample=SAMPLE_VOCAB.some(x=>vocabKey(x.word)===key);let on;if(sample){if(removed.has(key)){removed.delete(key);on=true}else{removed.add(key);on=false}Storage.set('vocabRemoved',[...removed])}else{if(arr.has(key)){arr.delete(key);on=false}else{arr.add(key);on=true}Storage.set('vocab',[...arr])}if(on)ensureVocabMeta(word);logEvent('api.POST','/api/vocabulary '+word+' saved='+on);return on},
 toggleSentence(i){const arr=new Set(Storage.get('favSentences',[]));arr.has(i)?arr.delete(i):arr.add(i);Storage.set('favSentences',[...arr]);logEvent('api.POST','/api/favorites/sentence '+i);return arr.has(i)}
};
