 function itemsForCategory(arr,cat,minCount){
   const primary=cat==='热门'?arr.filter(x=>['热门','日常生活','教育','职场'].includes(x.category)):arr.filter(x=>x.category===cat);
   if(primary.length)return primary.slice(0,minCount);
   const related=CATEGORY_RELATED[cat]||[];
   for(const fallback of related){const rows=arr.filter(x=>x.category===fallback);if(rows.length)return rows.slice(0,minCount)}
   return [];
 }
function renderHomeCategoryState(){ $$('#homeCategoryRow button').forEach(btn=>btn.classList.toggle('active',btn.dataset.cat===State.homeCategory)); const h=$('#continueTitle'); if(h)h.textContent=State.homeCategory==='热门'?'继续学习':'继续学习 · '+State.homeCategory; }
