function renderHomeHomeSections(){const videos=itemsForCategory(HOME_VIDEOS_DATA,State.homeCategory,4);$('#videoCards').innerHTML=videos.map(v=>`<article class="home-video-card" data-video="${v.id}" data-category="${v.category}"><div class="home-thumb"><img src="${v.cover}" alt="${v.title}"><span class="duration">${fmt(v.duration)}</span></div><div class="home-video-body"><h3>${v.title}</h3><div class="learn-progress"><i style="width:${v.progress}%"></i></div><div class="home-card-foot"><span>${v.creator}</span><span>已学 ${v.progress}%</span></div></div></article>`).join('');const collections=itemsForCategory(HOME_COLLECTIONS_DATA,State.homeCategory,5);$('#collectionCards').innerHTML=collections.map((c,idx)=>`<article class="home-collection-card" data-route="/compilation/36" data-category="${c.category}"><div class="collection-img"><img src="${c.cover}" alt="${c.title}"></div><div class="collection-info"><b>${c.title}</b><span>${c.count} 个视频</span></div></article>`).join('');const latest=itemsForCategory(HOME_VIDEOS_DATA.filter(v=>v.id!==2805),State.homeCategory,4);$('#homeLatestCards').innerHTML=latest.map(v=>`<article class="home-video-card" data-video="${v.id}" data-category="${v.category}"><div class="home-thumb"><img src="${v.cover}" alt="${v.title}"><span class="duration">${fmt(v.duration)}</span></div><div class="home-video-body"><h3>${v.title}</h3><div class="home-card-foot"><span>${v.creator}</span><span>${v.level}</span></div></div></article>`).join('');const daily=HOME_DAILY_MAP[State.homeCategory]||HOME_DAILY_MAP['热门'];const dailyImg=document.querySelector('.daily-thumb img'); if(dailyImg){dailyImg.src=daily.image;dailyImg.alt=daily.title;} const dailyH=$('.daily-pick h4'); const dailyP=$('.daily-pick p'); if(dailyH)dailyH.textContent=daily.title; if(dailyP)dailyP.textContent=daily.meta; bindCards();}

