function wordInfo(w){return DATA.dictionary[w]||{phon:'',meaning:'常用词',explain:'当前本地词库暂未收录这个词的详细释义。',levels:[]}}
function normalizeWord(t){return String(t||'').toLowerCase().replace(/[^a-z'-]/g,'')}
function normalizePhrase(t){return String(t||'').toLowerCase().replace(/[^a-z'\-]+/g,' ').trim().replace(/\s+/g,' ')}
function tokenHTML(text,idx,wordTimings=[]){
  const source=String(text||''),sentence=DATA.sentences[idx]||{};
  const words=[],re=/[A-Za-z][A-Za-z'-]*/g;let m;
  while((m=re.exec(source)))words.push({raw:m[0],word:normalizeWord(m[0]),start:m.index,end:m.index+m[0].length});
  if(!words.length)return escapeHtml(source);
  const phraseKeys=[...new Set([...sentenceKeywords(sentence),...Object.keys(DATA.dictionary).filter(k=>k.includes(' '))])]
    .map(x=>({key:x,parts:x.toLowerCase().split(/\s+/).map(normalizeWord).filter(Boolean)})).filter(x=>x.parts.length>1).sort((a,b)=>b.parts.length-a.parts.length);
  const phraseAt=new Map();
  for(let i=0;i<words.length;i++){
    for(const p of phraseKeys){
      if(i+p.parts.length>words.length||p.parts.some((part,k)=>words[i+k].word!==part))continue;
      let contiguous=true;for(let k=0;k<p.parts.length-1;k++)if(!/^\s+$/.test(source.slice(words[i+k].end,words[i+k+1].start))){contiguous=false;break}
      if(contiguous){phraseAt.set(i,{...p,endIndex:i+p.parts.length-1});break}
    }
  }
  let keywordTone=0;
  const renderToken=(raw,key,startIndex,endIndex,phrase=false)=>{
    const info=wordInfo(key),levels=State.settings.highlight===false?[]:(info.levels||[]).filter(x=>State.settings.levels.includes(x));
    const cls=['word-token',phrase?'phrase-token':'',...levels.map(x=>'level-'+x)].filter(Boolean);
    if(levels.length){keywordTone=(keywordTone%4)+1;cls.push('keyword-tone-'+keywordTone)}
    if(isVocabSaved(key))cls.push('saved');
    const rows=wordTimings.slice(startIndex,endIndex+1).filter(t=>Number.isFinite(Number(t?.start))&&Number.isFinite(Number(t?.end)));
    const timingAttrs=rows.length?` data-word-start="${Number(rows[0].start)}" data-word-end="${Number(rows[rows.length-1].end)}"`:'';
    return `<span class="${cls.join(' ')}" data-word="${escapeHtml(key)}" data-idx="${idx}"${phrase?' data-phrase="1"':''}${timingAttrs}>${escapeHtml(raw)}</span>`;
  };
  let out='',cursor=0,i=0;
  while(i<words.length){
    const phrase=phraseAt.get(i),last=phrase?.endIndex||i,first=words[i],end=words[last];
    out+=escapeHtml(source.slice(cursor,first.start));
    out+=renderToken(source.slice(first.start,end.end),phrase?phrase.key:first.word, i,last,!!phrase);
    cursor=end.end;i=last+1;
  }
  return out+escapeHtml(source.slice(cursor));
}
function sentenceKeywords(d){const manual=(d?.keyWords||d?.keywords||[]).map(x=>{const raw=String(x||'').trim();if(/\s/.test(raw))return normalizePhrase(raw);const collapsed=normalizeWord(raw);const phrase=Object.keys(DATA.dictionary).find(k=>k.includes(' ')&&normalizeWord(k)===collapsed);return phrase||collapsed}).filter(Boolean);if(manual.length)return [...new Set(manual)];const words=(d?.en||'').split(/\s+/).map(normalizeWord).filter(Boolean);const ranked=words.filter(w=>w.length>=4&&DATA.dictionary[w]&&(wordInfo(w).levels||[]).length);return [...new Set(ranked)].slice(0,1)}
function clozeTarget(d){return sentenceKeywords(d)[0]||''}
function clozeSentenceHTML(d,idx,interactive=false){const target=clozeTarget(d);if(!target)return tokenHTML(d.en,idx);let used=false;return d.en.split(/(\s+)/).map(p=>{if(/^\s+$/.test(p))return p;const m=p.match(/^([^A-Za-z']*)([A-Za-z'-]+)([^A-Za-z']*)$/);if(!m)return p;const w=normalizeWord(m[2]);if(w!==target||used)return tokenHTML(p,idx);used=true;const blank=interactive?`<span class="cloze-entry" data-answer="${target}" data-attempt="0"><input class="cloze-input" data-cloze-input="${idx}" autocomplete="off" autocapitalize="none" spellcheck="false" aria-label="输入缺少的重点词" placeholder="${'_'.repeat(Math.max(4,Math.min(10,target.length)))}"><button class="cloze-check" type="button">检查</button><small class="cloze-feedback"></small></span>`:`<span class="cloze-blank" data-cloze-word="${target}" aria-label="重点词填空">${'_'.repeat(Math.max(4,Math.min(10,target.length)))}</span>`;return `${m[1]}${blank}${m[3]}`}).join('')}
function checkClozeEntry(entry){const input=entry?.querySelector('.cloze-input'),feedback=entry?.querySelector('.cloze-feedback');if(!input||!feedback)return;const answer=normalizeWord(entry.dataset.answer||''),value=normalizeWord(input.value||'');let attempts=Number(entry.dataset.attempt||0)+1;entry.dataset.attempt=String(attempts);entry.classList.remove('correct','wrong');if(value===answer){entry.classList.add('correct');input.disabled=true;feedback.textContent=State.lang==='en'?'✓ Correct':'✓ 回答正确';feedback.dataset.noUiTranslate='';logEvent('cloze.correct',answer);return}entry.classList.add('wrong');if(attempts===1){const hint=answer.length>2?`${answer[0]}${' _'.repeat(Math.max(1,answer.length-2))} ${answer.at(-1)}`:answer[0]+' _';feedback.textContent=(State.lang==='en'?'Try again · Hint: ':'再试一次 · 提示：')+hint}else{feedback.textContent=(State.lang==='en'?'Answer: ':'答案：')+answer}logEvent('cloze.wrong',answer)}
function bindClozeInputs(root=document){root.querySelectorAll?.('.cloze-entry').forEach(entry=>{const input=entry.querySelector('.cloze-input'),btn=entry.querySelector('.cloze-check');if(btn)btn.onclick=e=>{e.stopPropagation();checkClozeEntry(entry)};if(input)input.onkeydown=e=>{e.stopPropagation();if(e.key==='Enter'){e.preventDefault();checkClozeEntry(entry)}}})}

function findSentence(t){const a=DATA.sentences;let lo=0,hi=a.length-1;while(lo<=hi){const m=(lo+hi)>>1,d=a[m];if(t<d.s)hi=m-1;else if(t>=d.e)lo=m+1;else return m}return Math.max(0,Math.min(a.length-1,lo-1))}
