  $('#dictWord').textContent=w;$('#dictPhon').textContent=d.phon;$('#dictMeaning').textContent=d.meaning;$('#dictExplain').textContent=d.explain;$('#dictContext').textContent=DATA.sentences[idx]?.en||'';
