uiMutationObserver.observe(document.body,{childList:true,subtree:true});


function activeVideoId(){const m=(State.route||'').match(/^\/video\/(\d+)/);return m?Number(m[1]):2805}
function hydrateManagedContent(){
  if(!window.ZoContent)return;
  try{
    const published=window.ZoContent.listVideos({publishedOnly:true});
    if(published.length){
      const normalized=published.map(v=>({id:Number(v.id),title:v.title,creator:v.creator||'Eastudy',duration:Number(v.duration)||30,level:v.level||'A2',cover:v.cover||'assets/images/home_video_1.png',date:(v.publishedAt||v.updatedAt||'').slice(0,10)}));
      DATA.videos.splice(0,DATA.videos.length,...normalized);
      const legacyProgress=new Map(HOME_VIDEOS_DATA.map(v=>[String(v.id),v.progress||0]));
      const studentVideos=published.map(v=>({id:Number(v.id),title:v.title,creator:v.creator||'Eastudy',level:v.level||'A2',duration:Number(v.duration)||30,cover:v.cover||'assets/images/home_video_1.png',category:v.category||'热门',progress:legacyProgress.get(String(v.id))||0}));
      HOME_VIDEOS_DATA.splice(0,HOME_VIDEOS_DATA.length,...studentVideos);
    }
    const cols=window.ZoContent.listCollections?.()||[];
    if(cols.length){const studentCollections=cols.filter(x=>x.status==='PUBLISHED').map(c=>({title:c.title,count:published.filter(v=>(v.collectionIds||[]).map(String).includes(String(c.id))).length,cover:c.cover||'assets/images/home_collection_1.png',category:c.title.includes('旅行')||c.title.includes('Travel')?'旅行':c.title.includes('美食')?'美食':c.title.includes('心理')?'心理':c.title.includes('自然')?'自然':c.title.includes('科技')?'科技':c.title.includes('学习')?'职场':c.title.includes('演讲')?'教育':'热门'}));HOME_COLLECTIONS_DATA.splice(0,HOME_COLLECTIONS_DATA.length,...studentCollections)}
  }catch(e){console.warn('Eastudy managed content hydration skipped',e)}
}
hydrateManagedContent();
bindAccountUI();
applyTheme();applySettings();applyLanguage();routeNow();bindCards();logEvent('app.boot','Eastudy production front-end ready');


// Learning dashboard: make time metrics and detail rows actionable without changing storage contracts.
function bindLearningTimeDetails(){
  document.querySelectorAll('.learning-time-card,.learning-mini-stat').forEach(card=>{
    if(card.dataset.timeBound)return; card.dataset.timeBound='1'; card.setAttribute('role','link'); card.setAttribute('tabindex','0');
    const go=()=>route('/learning'); card.addEventListener('click',go); card.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go()}});
  });
  document.querySelectorAll('.learning-detail-table .detail-row:not(.detail-head)').forEach(row=>{
    if(row.dataset.detailBound)return; row.dataset.detailBound='1'; row.setAttribute('role','link'); row.setAttribute('tabindex','0');
    const title=row.querySelector('b')?.textContent||''; const go=()=>{route('/video/2805');toast(`已打开：${title}`)}; row.addEventListener('click',go); row.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go()}});
  });
}
const learningObserver=new MutationObserver(()=>{if(document.getElementById('learningPage')?.classList.contains('active'))bindLearningTimeDetails()});
learningObserver.observe(document.body,{subtree:true,attributes:true,attributeFilter:['class']});
setTimeout(bindLearningTimeDetails,100);

